(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-288":{scenario:{company:"Mekong Data Systems",supervisor:{name:"Nghiêm Thu Hà",role:{vi:"Giám đốc Tư vấn Giải pháp",en:"Head of Solutions Consulting"}},ref_code:"RFP-3307",title:{vi:"Đúng yêu cầu. Đúng chi phí. Đúng cam kết.",en:"Right fit. Right cost. Right promise."},brief:{vi:"Bạn hoàn thiện hồ sơ trả lời RFP-3307 cho nhà máy điện tử cần phần mềm nhân sự cho 1200 người dùng, hợp đồng 36 tháng. Yêu cầu bắt buộc: dữ liệu lưu tại Việt Nam, môi trường riêng biệt; khách không có đội hạ tầng CNTT. Bảng giá mô phỏng: SaaS dùng chung (máy chủ ở nước ngoài) 4 USD, đám mây riêng tại Việt Nam 6 USD mỗi người dùng mỗi tháng; triển khai 38000 USD, chuyển đổi dữ liệu 12000 USD. Sửa phương án triển khai và TCO 3 năm, rồi lập báo cáo có căn cứ.",en:"You are finalizing the response to RFP-3307 for an electronics plant needing HR software for 1200 users on a 36-month contract. Mandatory: data stored in Vietnam in an isolated environment; the client has no IT infrastructure team. Training price list: shared SaaS (hosted abroad) 4 USD, private cloud in Vietnam 6 USD per user per month; implementation 38000 USD, data migration 12000 USD. Correct the deployment option and the 3-year TCO, then write an evidence-based report."},reference_title:{vi:"Ma trận đáp ứng & bảng tính TCO đã duyệt · RFP-3307",en:"Approved compliance matrix & TCO sheet · RFP-3307"},fields:[{id:"DEPLOY_MODEL",label:{vi:"Phương án triển khai",en:"Deployment option"},initial:"SAAS-SHARED",expected:"PRIVATE-VN",choices:["SAAS-SHARED","PRIVATE-VN","ON-PREM"],reference:"Ma trận đáp ứng yêu cầu bắt buộc",hint:{vi:"Loại phương án vi phạm yêu cầu lưu trữ dữ liệu, rồi loại phương án khách không tự vận hành được.",en:"Rule out the option that breaks data residency, then the one the client cannot operate."}},{id:"TCO_USD",label:{vi:"TCO 3 năm (USD)",en:"3-year TCO (USD)"},initial:"210800",expected:"309200",reference:"Bảng tính TCO",ref_value:{vi:"1200 người dùng x 36 tháng x đơn giá phương án đã chọn; triển khai 38000 + chuyển đổi dữ liệu 12000 USD",en:"1200 users x 36 months x price of the chosen option; implementation 38000 + data migration 12000 USD"},hint:{vi:"Đơn giá phải khớp phương án đáp ứng yêu cầu bắt buộc, và không bỏ sót chi phí một lần nào.",en:"The unit price must match the compliant option, and no one-time cost may be left out."}}],sop32:{vi:"TCO 3 năm = số người dùng x đơn giá tháng của phương án đáp ứng yêu cầu bắt buộc x 36 + mọi chi phí một lần (triển khai, chuyển đổi dữ liệu). Đơn giá trong bài là số liệu mô phỏng.",en:"3-year TCO = users x monthly price of the option meeting all mandatory requirements x 36 + every one-time cost (implementation, data migration). Prices are training figures."},context:{label:"RFP / RFP-3307",metrics:[{label:{vi:"Số người dùng",en:"Named users"},value:"1200"},{label:{vi:"Kỳ hợp đồng (tháng)",en:"Contract term (months)"},value:"36"},{label:{vi:"Nơi lưu trữ bắt buộc",en:"Mandatory data residency"},value:"VN"},{label:{vi:"Chi phí một lần",en:"One-time costs"},value:"50,000 USD"}]},crisis:{vi:"Giám đốc kinh doanh yêu cầu: “Đánh ‘Đáp ứng đầy đủ’ cho cả 142 yêu cầu, kể cả đăng nhập một lần với hệ thống chấm công cũ mà sản phẩm chưa hỗ trợ. Ký được hợp đồng rồi tùy biến sau.”",en:"The sales director demands: “Mark all 142 requirements ‘Fully compliant’, including single sign-on with the legacy time-attendance system the product does not support. Sign first, customize later.”"},options:{safe:{vi:"Ghi trung thực từng mức đáp ứng (đầy đủ, một phần, lộ trình, tùy biến có phí), báo Giám đốc Tư vấn Giải pháp và đề xuất tích hợp qua API kèm ước lượng công.",en:"Record each compliance level honestly (full, partial, roadmap, paid customization), inform the Head of Solutions and propose an API integration with an effort estimate."},shortcut:{vi:"Đánh đáp ứng đầy đủ toàn bộ cho kịp hạn nộp, xử lý chênh lệch khi triển khai.",en:"Mark everything fully compliant to meet the deadline and deal with the gaps during delivery."},wait:{vi:"Không trả lời mục tích hợp và chờ kinh doanh tự quyết định nội dung nộp.",en:"Leave the integration items blank and wait for Sales to decide what to submit."}},questions:{vi:["Vì sao chọn PRIVATE-VN thay vì SAAS-SHARED hay ON-PREM? Yêu cầu bắt buộc nào quyết định lựa chọn?","Trình bày cách tính TCO 3 năm và rủi ro pháp lý, uy tín khi khai năng lực không có thật trong hồ sơ thầu."],en:["Why choose PRIVATE-VN over SAAS-SHARED or ON-PREM? Which mandatory requirement drives the choice?","Explain the 3-year TCO calculation and the legal and reputational risk of claiming capabilities that do not exist."]},hints:{vi:["Đặt bản nháp cạnh ma trận đáp ứng, đánh dấu yêu cầu bắt buộc mà phương án hiện tại không thỏa.","Tính TCO theo SOP mục 3.2: chi phí định kỳ của đủ kỳ hợp đồng cộng mọi chi phí một lần.","Đọc lại SOP mục 4.2: không cam kết năng lực chưa có; khoảng trống phải được ghi rõ và báo cáo."],en:["Place the draft next to the compliance matrix and flag the mandatory item the current option fails.","Compute TCO per SOP 3.2: recurring cost over the full term plus every one-time cost.","Re-read SOP 4.2: never commit capabilities that do not exist; gaps must be stated and escalated."]}},learning:{summary:{vi:"Chuyên viên tư vấn giải pháp (pre-sales) là cầu nối giữa kinh doanh và kỹ thuật: tìm hiểu quy trình và bài toán của khách hàng, thiết kế kiến trúc giải pháp, trình diễn sản phẩm, trả lời RFP, chạy thử nghiệm (POC) và lập phương án chi phí. Nghề đòi hỏi hiểu sâu sản phẩm, kiến trúc hệ thống, bảo mật và tích hợp, đồng thời trung thực về năng lực để thương vụ thắng bền vững và triển khai thành công.",en:"A pre-sales solutions consultant bridges sales and engineering: understanding the client's processes and problems, designing the solution architecture, demonstrating the product, answering RFPs, running proofs of concept (POC) and building the cost case. The role needs deep product, architecture, security and integration knowledge, plus honesty about capabilities so deals are won sustainably and delivered successfully."},responsibilities:{vi:["Tổ chức buổi khảo sát nhu cầu, lập bản đồ quy trình hiện tại và mục tiêu của khách hàng.","Thiết kế kiến trúc, định cỡ hạ tầng và chọn phương án triển khai phù hợp yêu cầu phi chức năng.","Trình diễn sản phẩm theo kịch bản nghiệp vụ và điều phối thử nghiệm POC.","Trả lời RFP, RFI, lập ma trận đáp ứng và bảng tính TCO, ROI.","Bàn giao phạm vi đã cam kết cho đội triển khai, tránh hụt kỳ vọng sau ký hợp đồng."],en:["Run discovery workshops and map the client's current and target processes.","Design the architecture, size the infrastructure and choose a deployment option that meets non-functional needs.","Deliver scenario-based demos and coordinate POCs.","Answer RFPs and RFIs, build the compliance matrix and the TCO and ROI sheets.","Hand the committed scope to the delivery team to avoid expectation gaps after signing."]},competencies:[{name:{vi:"Khám phá nhu cầu",en:"Discovery"},desc:{vi:"Đặt câu hỏi mở, tìm nỗi đau nghiệp vụ, tiêu chí quyết định và người phê duyệt kỹ thuật.",en:"Ask open questions to find business pain, decision criteria and technical approvers."}},{name:{vi:"Thiết kế giải pháp",en:"Solution design"},desc:{vi:"Kết hợp mô-đun, tích hợp, bảo mật và hạ tầng thành kiến trúc khả thi, có giới hạn rõ.",en:"Combine modules, integrations, security and infrastructure into a feasible architecture with clear limits."}},{name:{vi:"Trình diễn thuyết phục",en:"Compelling demos"},desc:{vi:"Trình diễn theo kịch bản của chính khách hàng, nhấn vào giá trị thay vì liệt kê tính năng.",en:"Demo the client's own scenarios and stress value instead of listing features."}},{name:{vi:"Kinh tế giải pháp",en:"Solution economics"},desc:{vi:"Tính TCO, ROI, so sánh mô hình cấp phép và chi phí một lần một cách minh bạch.",en:"Compute TCO and ROI and compare licensing models and one-time costs transparently."}},{name:{vi:"Trung thực về năng lực",en:"Capability honesty"},desc:{vi:"Ghi đúng mức đáp ứng, nêu khoảng trống và đề xuất giải pháp thay thế có ước lượng.",en:"State true compliance levels, disclose gaps and propose estimated alternatives."}}],knowledge:{vi:["Mô hình triển khai SaaS dùng chung, đám mây riêng, tại chỗ và mô hình trách nhiệm chia sẻ về bảo mật.","ISO/IEC 27001 về hệ thống quản lý an toàn thông tin và báo cáo SOC 2 khi khách hàng thẩm định nhà cung cấp.","Yêu cầu phi chức năng: hiệu năng, độ sẵn sàng theo SLA, khả năng mở rộng, tích hợp API, đăng nhập một lần (SSO).","Phương pháp tính TCO, ROI và các mô hình cấp phép theo người dùng định danh, đồng thời hoặc theo gói.","Quy định hiện hành về an ninh mạng và bảo vệ dữ liệu cá nhân, gồm yêu cầu lưu trữ dữ liệu tại Việt Nam trong một số trường hợp."],en:["Shared SaaS, private cloud and on-premise deployment models and the shared security responsibility model.","ISO/IEC 27001 for information security management and SOC 2 reports used in vendor due diligence.","Non-functional requirements: performance, SLA availability, scalability, API integration and single sign-on (SSO).","TCO and ROI methods and named-user, concurrent and bundle licensing models.","Current cybersecurity and personal data protection rules, including data localization in Vietnam in certain cases."]},tools:["Môi trường demo / sandbox","Công cụ vẽ kiến trúc giải pháp","Bảng tính TCO / ROI","Thư viện câu trả lời RFP","Hệ thống CRM"],kpis:{vi:["Tỷ lệ thắng kỹ thuật ở các thương vụ có pre-sales tham gia.","Thời gian hoàn thành hồ sơ RFP so với hạn nộp.","Tỷ lệ POC chuyển thành hợp đồng.","Số yêu cầu thay đổi phát sinh do cam kết sai phạm vi khi bán (mục tiêu bằng 0)."],en:["Technical win rate on deals with pre-sales involvement.","RFP completion time versus the submission deadline.","POC-to-contract conversion rate.","Change requests caused by mis-sold scope (target zero)."]},day:[{time:"08:30",vi:"Rà soát cơ hội mới trên CRM, chuẩn bị câu hỏi khảo sát cho từng khách hàng.",en:"Review new CRM opportunities and prepare discovery questions for each client."},{time:"10:00",vi:"Hội thảo khảo sát quy trình nhân sự, chấm công với nhà máy khách hàng.",en:"Discovery workshop on HR and time-attendance processes at a client plant."},{time:"13:30",vi:"Trình diễn sản phẩm theo kịch bản tính lương ca kíp của khách hàng.",en:"Demo the product using the client's shift payroll scenario."},{time:"15:30",vi:"Hoàn thiện ma trận đáp ứng RFP và bảng tính TCO, gửi rà soát nội bộ.",en:"Complete the RFP compliance matrix and TCO sheet for internal review."},{time:"17:00",vi:"Ghi chú bàn giao phạm vi cho đội triển khai và cập nhật CRM.",en:"Write scope handover notes for delivery and update the CRM."}],mistakes:{vi:["Chọn gói chuẩn rẻ nhất mà bỏ qua yêu cầu bắt buộc phi chức năng như nơi lưu trữ dữ liệu.","Tính TCO thiếu chi phí một lần hoặc chỉ tính 12 tháng cho hợp đồng nhiều năm.","Đánh đáp ứng đầy đủ cho tính năng chưa có, gây tranh chấp và lỗ khi triển khai."],en:["Picking the cheapest standard package while ignoring mandatory non-functional needs such as data residency.","Leaving one-time costs out of TCO or counting only 12 months of a multi-year contract.","Marking missing features fully compliant, causing disputes and losses in delivery."]},career:[{vi:"Kỹ sư hỗ trợ kỹ thuật / triển khai",en:"Support or implementation engineer"},{vi:"Chuyên viên tư vấn giải pháp (pre-sales)",en:"Pre-sales solutions consultant"},{vi:"Kiến trúc sư giải pháp cấp cao",en:"Senior solutions architect"},{vi:"Giám đốc tư vấn giải pháp",en:"Head of solutions consulting"}],glossary:[{term:"RFP",vi:"Hồ sơ mời đề xuất: tài liệu khách hàng nêu yêu cầu và tiêu chí đánh giá nhà cung cấp.",en:"Request for proposal: the client's document of requirements and vendor evaluation criteria."},{term:"POC",vi:"Thử nghiệm chứng minh khái niệm trên dữ liệu hoặc quy trình thật trong phạm vi giới hạn.",en:"Proof of concept on real data or processes within a limited scope."},{term:"TCO",vi:"Tổng chi phí sở hữu trong suốt kỳ sử dụng, gồm chi phí định kỳ và chi phí một lần.",en:"Total cost of ownership over the usage period, recurring plus one-time costs."},{term:"Compliance matrix",vi:"Ma trận đáp ứng: bảng ghi mức độ đáp ứng của giải pháp với từng yêu cầu.",en:"A table stating how the solution meets each requirement."},{term:"SSO",vi:"Đăng nhập một lần: người dùng xác thực một lần để truy cập nhiều ứng dụng.",en:"Single sign-on: users authenticate once to access several applications."}],quiz:[{q:{vi:"800 người dùng, đơn giá 5 USD/người dùng/tháng, hợp đồng 24 tháng, chi phí triển khai một lần 20000 USD. TCO là bao nhiêu?",en:"800 users at 5 USD per user per month, a 24-month contract and a one-time implementation of 20000 USD. What is the TCO?"},options:{vi:["96000 USD","116000 USD","68000 USD","136000 USD"],en:["96000 USD","116000 USD","68000 USD","136000 USD"]},answer:1,explain:{vi:"800 x 5 x 24 = 96000, cộng 20000 chi phí một lần = 116000 USD.",en:"800 x 5 x 24 = 96000, plus the 20000 one-time cost = 116000 USD."}},{q:{vi:"RFP bắt buộc lưu dữ liệu tại Việt Nam, còn gói chuẩn lưu ở nước ngoài. Bạn làm gì?",en:"The RFP mandates data storage in Vietnam but the standard package is hosted abroad. What do you do?"},options:{vi:["Đánh đáp ứng và hứa chuyển dữ liệu sau","Bỏ trống dòng yêu cầu đó","Chỉ ghi chú nhỏ ở phụ lục","Đề xuất phương án lưu trữ tại Việt Nam hoặc ghi rõ không đáp ứng"],en:["Mark it compliant and promise to move data later","Leave that requirement blank","Add a small note in an annex","Offer a Vietnam-hosted option or state non-compliance clearly"]},answer:3,explain:{vi:"Yêu cầu bắt buộc không đáp ứng sẽ bị loại hoặc gây vi phạm; phải có phương án phù hợp hoặc nói rõ.",en:"An unmet mandatory requirement leads to disqualification or breach; offer a fit or say so clearly."}},{q:{vi:"Giám đốc kinh doanh muốn đánh ‘Đáp ứng đầy đủ’ cho tính năng chưa có. Phương án đúng là gì?",en:"The sales director wants a missing feature marked ‘Fully compliant’. What is right?"},options:{vi:["Ghi đúng mức đáp ứng, báo cấp trên và đề xuất giải pháp thay thế có ước lượng","Làm theo vì đã có chỉ đạo","Xóa yêu cầu khỏi ma trận","Đánh đáp ứng nhưng tăng giá dự phòng"],en:["State the true level, escalate and propose an estimated alternative","Comply because it is an instruction","Delete the requirement from the matrix","Mark it compliant but add a hidden buffer"]},answer:0,explain:{vi:"Khai năng lực không có thật là gian dối trong chào thầu và dẫn tới tranh chấp hợp đồng.",en:"Claiming non-existent capability is misrepresentation in bidding and leads to contract disputes."}},{q:{vi:"Tiêu chuẩn nào quy định hệ thống quản lý an toàn thông tin có thể được chứng nhận?",en:"Which standard specifies a certifiable information security management system?"},options:{vi:["ISO 9001","ISO 14001","ISO/IEC 27001","ISO 45001"],en:["ISO 9001","ISO 14001","ISO/IEC 27001","ISO 45001"]},answer:2,explain:{vi:"ISO/IEC 27001 quy định yêu cầu cho ISMS; ISO 9001 là chất lượng, 14001 là môi trường, 45001 là an toàn lao động.",en:"ISO/IEC 27001 sets ISMS requirements; 9001 is quality, 14001 environment and 45001 occupational safety."}}],tools_en:["Demo / sandbox environment","Solution architecture diagramming tool","TCO / ROI spreadsheet","RFP response library","CRM system"]}}})})(window.KKR);
